def nested(side, offset=0, size=19):
 g=[[0]*size for _ in range(size)]
 lo,hi=offset,offset+side-1
 for r in range(lo,hi+1):
  for c in range(lo,hi+1):
   if r in (lo,hi) or c in (lo,hi):g[r][c]=5
 il,ih=lo+2,hi-2; band=2
 while il<=ih:
  for r in range(lo+1,hi):
   for c in range(lo+1,hi):
    if r in (lo+1,hi-1) or c in (lo+1,hi-1):g[r][c]=band
  for r in range(il,ih+1):
   for c in range(il,ih+1):
    if r in (il,ih) or c in (il,ih):g[r][c]=5
  lo,hi=il,ih;il,ih=lo+2,hi-2;band=0 if band==2 else 2
 return g
